Tests.EqualCheck("match two capturing groups in order", true, matchPattern("cat and dog, cat and dog", `(\w+) and (\w+), \1 and \2`))
Tests.EqualCheck("do not match when groups are inverted in backreference", false, matchPattern("cat and dog, dog and cat", `(\w+) and (\w+), \1 and \2`))
Tests.EqualCheck("match reversed backreferences palindromic pattern", true, matchPattern("100 test test 100", `^(\d+) (\w+) \2 \1$`))
Tests.EqualCheck("do not match when reversed backreferences differ", false, matchPattern("100 test other 100", `^(\d+) (\w+) \2 \1$`))
Tests.EqualCheck("match group referenced three times", true, matchPattern("go-go-go", `^(\w+)-\1-\1$`))
Tests.EqualCheck("do not match when third reference differs", false, matchPattern("go-go-stop", `^(\w+)-\1-\1$`))
Tests.EqualCheck("match three distinct groups", true, matchPattern("a b c a b c", `^(\w+) (\w+) (\w+) \1 \2 \3$`))
Tests.EqualCheck("do not match when one of three groups differs", false, matchPattern("a b c a b d", `^(\w+) (\w+) (\w+) \1 \2 \3$`))
Tests.EqualCheck("match character ranges with multiple backreferences", true, matchPattern("AB-12-AB-12", `^([A-Z]+)-(\d+)-\1-\2$`))
Tests.EqualCheck("do not match when range group does not match backreference", false, matchPattern("AB-12-CD-12", `^([A-Z]+)-(\d+)-\1-\2$`))
Tests.EqualCheck("match multiple backreferences combined with wildcard", true, matchPattern("cat.dog.cat.dog", `^(\w+)\.(\w+)\.\1\.\2$`))
Tests.EqualCheck("match multiple groups with alternation", true, matchPattern("red and blue, red and blue", `(red|green) and (blue|yellow), \1 and \2`))
Tests.EqualCheck("do not match multiple groups with mismatched alternation", false, matchPattern("red and blue, green and blue", `(red|green) and (blue|yellow), \1 and \2`))
Tests.EqualCheck("match multiple backreferences in unanchored line", true, matchPattern("prefix foo bar foo bar suffix", `(\w+) (\w+) \1 \2`))
Tests.EqualCheck("single backreference still works", true, matchPattern("cat and cat", `(cat) and \1`))
Tests.EqualCheck("empty pattern matches any line", true, matchPattern("hello", ""))
